import { SectionTitle } from '@/components/ui/SectionTitle'
import { Reveal } from '@/components/ui/Reveal'
import { SOCIALS } from '@/components/layout/SocialLinks'
import { buttonClass } from '@/components/ui/Button'
import { useLang } from '@/hooks/useLang'
import { useAutoplayInView } from '@/hooks/useAutoplayInView'
import { imgSrc, imgSrcSet } from '@/lib/products'
import { FollowLink } from '@/components/ui/ContactButton'

/**
 * Edit these lists to change the gallery (files live in /public, generated by `npm run import-media`).
 * Layout: 2 tall videos + 4 photos fill the grid exactly (2 rows × 4 columns on desktop, 2 columns on phones).
 */
const PHOTOS = Array.from({ length: 4 }, (_, i) => `/images/gallery/${i + 1}`)
const VIDEOS = [
  { src: '/videos/gallery/follow.mp4', poster: '/images/products/glowing-logo/2-960.webp', labelKey: 'gallery.videoFollow' },
  { src: '/videos/gallery/logo-glow.mp4', poster: '/images/products/glowing-logo/4-960.webp', labelKey: 'gallery.videoLogo' },
]

function VideoTile({ video, delay = 0 }: { video: (typeof VIDEOS)[number]; delay?: number }) {
  const { t } = useLang()
  const ref = useAutoplayInView<HTMLVideoElement>()
  const label = t(video.labelKey)
  return (
    <Reveal delay={delay} className="relative row-span-2 overflow-hidden rounded-2xl border border-white/[0.06] bg-night-800">
      <video ref={ref} className="h-full w-full object-cover" src={video.src} poster={video.poster} muted loop playsInline preload="none" aria-label={label} />
      <span className="absolute bottom-3 left-3 rounded-full bg-night-950/70 px-2.5 py-1 text-[11px] font-medium text-white backdrop-blur">▶ {label}</span>
    </Reveal>
  )
}

function PhotoTile({ base, n }: { base: string; n: number }) {
  const { t } = useLang()
  return (
    <Reveal delay={0.03 * (n % 4)} className="relative overflow-hidden rounded-2xl border border-white/[0.06] bg-night-800">
      <img
        src={imgSrc(base, 960)}
        srcSet={imgSrcSet(base)}
        sizes="(min-width:1024px) 25vw, 50vw"
        alt={t('gallery.photoAlt', { n })}
        loading="lazy"
        decoding="async"
        className="h-full w-full object-cover transition-transform duration-700 hover:scale-105"
      />
    </Reveal>
  )
}

export function Gallery() {
  const { t } = useLang()
  return (
    <section className="section bg-night-950" aria-labelledby="gallery-title">
      <div className="container">
        <SectionTitle id="gallery-title" eyebrow={t('gallery.eyebrow')} title={t('gallery.title')} subtitle={t('gallery.subtitle')} />

        <div className="grid grid-flow-dense auto-rows-[150px] grid-cols-2 gap-3 sm:auto-rows-[180px] sm:gap-4 lg:grid-cols-4">
          <VideoTile video={VIDEOS[0]} />
          <PhotoTile base={PHOTOS[0]} n={1} />
          <PhotoTile base={PHOTOS[1]} n={2} />
          <VideoTile video={VIDEOS[1]} delay={0.1} />
          {PHOTOS.slice(2).map((p, i) => (
            <PhotoTile key={p} base={p} n={i + 3} />
          ))}
        </div>

        <div className="mt-10 flex flex-col items-center gap-4">
          <p className="text-sm text-mist-400">{t('gallery.more')}</p>
          <div className="flex flex-wrap justify-center gap-3">
            {SOCIALS.map(({ key, label, Icon }) => (
              <FollowLink key={key} network={key} className={buttonClass('secondary', 'md')}>
                <Icon size={18} />
                {label}
              </FollowLink>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}
